import {installPublicAPIClient,apiAsset} from '/api-client.js';
import {mountPortalHome,mountPortalDetail,detailTitles,disposePortalHome} from '/portal/app.js';
import {initStudio,disposeStudio} from '/studio.js';
import {qrExample,operatingGuide} from '/upgrade.js';
import {faqView,productCardsView,sampleProducts} from '/shared.js';
import {wireDetails} from '/content.js';
import {serviceView} from '/service.js';
import {initExperience,disposeExperience} from '/experience.js';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const main=$('#main');
const embeddedConfig=document.getElementById('site-config');
installPublicAPIClient();
let config={area:'Vinh, Nghệ An',phone:'0332357455',smallBase:350000,fullBase:500000,boxBase:100000,boxUnit:10000,rentalDays:5,extraBoxDay:5000,priceMode:'reference'};
if(embeddedConfig){try{config={...config,...JSON.parse(embeddedConfig.textContent)};}catch{}}
const money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(n||0);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const services={small:'Gọn nhẹ',full:'Trọn gói',boxes:'Chỉ thuê hộp',cleaning:'Dọn phòng',handover:'Bàn giao phòng'};
const categories={all:'Tất cả',furniture:'Nội thất',electronics:'Đồ điện',books:'Sách',clothing:'Quần áo',other:'Đồ khác'};
const modes={buyback:'Thu mua',consign:'Ký gửi',recycle:'Phân loại / thu gom',none:'Không có'};
const slots={morning:'Buổi sáng · 08:00–12:00',afternoon:'Buổi chiều · 13:00–17:00',evening:'Buổi tối · 17:00–20:00'};
function toast(text){const el=$('#toast');el.textContent=text;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3800);}
async function api(url,data){const res=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),credentials:'same-origin'});const result=await res.json();if(!res.ok){const error=new Error(result.error||'Chưa thể hoàn tất. Vui lòng thử lại.');error.status=res.status;throw error;}return result;}
function routePath(){return location.pathname.replace(/\/+$/,'')||'/';}
let renderedPath=routePath()+location.search;
if(!Number.isInteger(history.state?.bxIndex))history.replaceState({bxIndex:0},'');
function closeMenu(){$('.mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Mở menu');}
function scrollToHash(){if(location.hash){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{return;}document.getElementById(id)?.scrollIntoView({block:'start',behavior:'instant'});}else window.scrollTo({top:0,behavior:'instant'});}
function rememberBooking(){const form=$('#booking-form')||$('#survey-form');if(form)captureFields(form,bookingDraft);}
function go(url){const next=new URL(url,location.href);if(next.pathname==='/'&&next.hash==='#huong-dan'){next.pathname='/huong-dan';next.hash='';}rememberBooking();const same=next.pathname+next.search===renderedPath;history.pushState({bxIndex:(history.state?.bxIndex||0)+1},'',next.pathname+next.search+next.hash);closeMenu();$$('.n7-menu[open]').forEach(menu=>menu.open=false);if(same){scrollToHash();return;}render().then(()=>{if(!next.hash)window.scrollTo({top:0,behavior:'instant'});});}
$('#route-back').addEventListener('click',()=>{rememberBooking();if(history.state?.bxIndex>0)history.back();else go('/');});
document.addEventListener('keydown',event=>{if(event.key==='Escape')$$('.n7-menu[open]').forEach(menu=>menu.open=false);});
document.addEventListener('click',event=>{if(!event.target.closest('.n7-menu'))$$('.n7-menu[open]').forEach(menu=>menu.open=false);});
document.addEventListener('click',event=>{const link=event.target.closest('a');if(!link||event.ctrlKey||event.metaKey||event.shiftKey||link.target||link.hasAttribute('download'))return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!url.pathname.startsWith('/')||url.pathname.startsWith('/api/'))return;event.preventDefault();go(url.pathname+url.search+url.hash);});
window.addEventListener('popstate',()=>{rememberBooking();if(routePath()+location.search===renderedPath)scrollToHash();else render();});
$('.menu-toggle').addEventListener('click',()=>{const nav=$('.mobile-nav'),open=nav.hidden;nav.hidden=!open;$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Đóng menu':'Mở menu');});
function top(title,description,crumb=title){return `<section class="page-top container"><div class="breadcrumb"><a href="/">Trang chủ</a><span>/</span><span>${esc(crumb)}</span></div><h1>${title}</h1><p>${description}</p></section>`;}
function priceNotice(){return config.priceMode==='reference'?'<div class="notice">Bảng giá dự kiến cho giai đoạn thử nghiệm tại '+esc(config.area)+'. Giá chính thức được xác nhận sau khảo sát; chưa bao gồm khoản đặt cọc hộp nếu có.</div>':'<div class="notice green">Báo giá theo thông tin bạn cung cấp. BOXANH xác nhận giá cuối cùng sau khảo sát, trước khi nhận lịch.</div>';}
function faq(){return faqView({config,esc});}

function productCards(items,sample=false){return productCardsView(items,sample,{config,money,esc,categories});}

let routeGeneration=0;
async function render(){renderedPath=routePath()+location.search;disposePortalHome();disposeExperience();disposeStudio();const generation=++routeGeneration;$('.mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');$('.menu-toggle').setAttribute('aria-label','Mở menu');const route=routePath();document.body.dataset.route=route;const hub=document.querySelector('[data-service-masthead]');if(hub)hub.hidden=route!=='/';$$('.desktop-nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===route));document.title=({ '/':'BOXANH — Chuyển trọ Vinh, dọn phòng & bàn giao','/dat-lich':'Nhận báo giá dịch vụ — BOXANH','/dich-vu':'Dịch vụ & bảng giá — BOXANH','/do-cu':'Vòng đời mới — BOXANH','/gui-do':'Thu mua & ký gửi — BOXANH','/tra-cuu':'Tra cứu yêu cầu — BOXANH','/quan-tri':'Vận hành — BOXANH','/ve-boxanh':'Về BOXANH','/chinh-sach':'Chính sách — BOXANH','/tro-ly-ai':'Bơ · Trợ lý BOXANH','/ho-tro':'CSKH & sự cố — BOXANH','/hop-minh-hoa':'Thông tin hộp minh họa — BOXANH'})[route]||'BOXANH';if(route==='/'){mountPortalHome(main,{config,onQuote(input){bookingDraft={...bookingDraft,...input,consent:false};bookingStep=1;go('/dat-lich');}});}else if(detailTitles[route]){mountPortalDetail(main,{route,config,onQuote(input){bookingDraft={...bookingDraft,...input,consent:false};bookingStep=1;go('/dat-lich');}});}else if(route==='/dich-vu'){main.innerHTML=servicePage();initExperience({api,money,esc,onQuote(){go('/dat-lich');}});}else if(route==='/dat-lich'){bookingPage();}else if(route==='/gui-do'){goodsPage();}else if(route==='/do-cu'){await marketPage(generation);}else if(route==='/tra-cuu'){trackingPage();}else if(route==='/ve-boxanh'){main.innerHTML=aboutPage();}else if(route==='/chinh-sach'){main.innerHTML=policyPage();}else if(route==='/hop-minh-hoa'){main.innerHTML=qrExample();}else if(route==='/ho-tro'){supportPage();}else if(route==='/quan-tri'){await adminPage(generation);}else main.innerHTML=top('Trang này chưa có.','Bạn có thể quay về trang chủ để tiếp tục.')+'<div class="container section"><a class="button primary" href="/">Về trang chủ</a></div>';if(generation===routeGeneration){$$('.bx8-service').forEach(a=>{if(a.getAttribute('href')===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const label=detailTitles[route]||({'/dat-lich':'Nhận báo giá','/dich-vu':'Dịch vụ & bảng giá','/gui-do':'Thu mua & ký gửi','/do-cu':'Vòng đời mới','/tra-cuu':'Tra cứu','/ho-tro':'CSKH & liên hệ','/ve-boxanh':'Về BOXANH','/chinh-sach':'Chính sách','/quan-tri':'Cổng vận hành','/hop-minh-hoa':'Thẻ hộp minh họa'})[route]||'BOXANH';$('#route-backbar').hidden=route==='/';$('#route-current').textContent=label;if(detailTitles[route])document.title=label+' — BOXANH';wireDetails(main);initStudio(main);if(location.hash)scrollToHash();else {window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}}}
function servicePage(){return serviceView({config,money,esc,faq});}

let bookingStep=1;
function freshBooking(){return {requestId:crypto.randomUUID(),service:'full',boxes:10,bulky:0,packing:false,distance:5,originFloor:0,destinationFloor:0,originElevator:false,destinationElevator:false,origin:'',destination:'',date:new Date(Date.now()+7*3600000+2*86400000).toISOString().slice(0,10),slot:'morning',surplusMode:'none',surplusDescription:'',photos:[],name:'',phone:'',notes:'',consent:false};}
let bookingDraft=freshBooking();
let quoteVersion=0;
function inputField(label,name,type='text',value='',extra='',hint=''){return `<label class="field">${label}<input type="${type}" name="${name}" value="${esc(value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</label>`;}
function selectField(label,name,options,value,hint=''){return `<label class="field">${label}<select name="${name}">${Object.entries(options).map(([k,v])=>`<option value="${esc(k)}" ${value===k?'selected':''}>${esc(v)}</option>`).join('')}</select>${hint?`<small>${hint}</small>`:''}</label>`;}
function photoField(photos=[],product=false,incident=false){return `<div class="upload-zone"><strong>${product?'Ảnh thật của món đồ sẽ được công khai':incident?'Ảnh hiện trạng giúp đối chiếu sự cố':'Ảnh đồ đạc giúp khảo sát chính xác hơn'}</strong><p>${product?'Chọn 1 ảnh thật của món đồ.':'Tối đa 4 ảnh.'} JPG, PNG hoặc WebP; mỗi ảnh tối đa 2 MB.<br>Tránh chụp giấy tờ hoặc thông tin riêng tư không cần thiết.</p><label><span class="sr-only">${product?'Chọn ảnh thật của món đồ':incident?'Chọn ảnh hiện trạng sự cố':'Chọn ảnh đồ đạc'}</span><input type="file" name="photos" accept="image/jpeg,image/png,image/webp" ${product?'required':'multiple'} data-max="${product?1:4}"></label><div class="upload-previews">${photos.map(p=>`<img src="${esc(p.data)}" alt="Ảnh đồ đạc đã chọn">`).join('')}</div></div>`;}
function captureFields(form,draft){for(const input of $$('input[name],select[name],textarea[name]',form)){if(input.type==='file')continue;if(input.type==='radio'){if(input.checked)draft[input.name]=input.value;}else if(input.type==='checkbox')draft[input.name]=input.checked;else if(input.type==='number')draft[input.name]=Number(input.value);else draft[input.name]=input.value;}}
function formError(form,error){let el=$('.form-error',form);if(!el){el=document.createElement('div');el.className='form-error';el.setAttribute('role','alert');form.prepend(el);}el.textContent=error.message||error;el.scrollIntoView({block:'nearest',behavior:'instant'});}
function wirePhotos(form,draft){const field=$('input[type=file]',form);if(!field)return;field.addEventListener('change',async()=>{try{const files=[...field.files],max=Number(field.dataset.max||4);if(files.length>max)throw new Error(`Chọn tối đa ${max} ảnh.`);for(const f of files){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024)throw new Error('Chọn ảnh JPG, PNG hoặc WebP nhỏ hơn 2 MB.');}const photos=await Promise.all(files.map(f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({data:reader.result});reader.onerror=()=>reject(new Error('Chưa đọc được ảnh.'));reader.readAsDataURL(f);})));draft.photos=photos;$('.upload-previews',form).innerHTML=photos.map(p=>`<img src="${esc(p.data)}" alt="Ảnh đồ đạc đã chọn">`).join('');}catch(error){field.value='';draft.photos=[];$('.upload-previews',form).innerHTML='';formError(form,error);}});}
function bookingPage(){const requested=new URLSearchParams(location.search).get('goi');if(requested&&services[requested]){if(requested!==bookingDraft.service)bookingStep=1;bookingDraft.service=requested;}if(['cleaning','handover'].includes(bookingDraft.service)){surveyRequestPage();return;}const d=bookingDraft;const steps=['Gói & đồ đạc','Lịch & địa chỉ','Đồ không mang đi','Liên hệ & gửi'];let content='';if(bookingStep===1){content=`<div class="form-title"><h2>Chọn cách bạn muốn chuyển.</h2><p>Ước tính số hộp và món đồ lớn. Có thể điều chỉnh sau khảo sát.</p></div><div class="service-options">${Object.entries(services).filter(([k])=>!['cleaning','handover'].includes(k)).map(([k,v])=>`<label class="service-option"><input type="radio" name="service" value="${k}" ${d.service===k?'checked':''}><span><strong>${v}</strong><small>${k==='small'?'Bạn chủ động đóng đồ, BOXANH hỗ trợ chuyển.':k==='full'?'Hỗ trợ đóng gói, vận chuyển và xử lý đồ thừa.':'Giao hộp và thu hồi; bạn tự sắp xếp vận chuyển.'}</small></span></label>`).join('')}</div><div class="field-grid">${inputField('Số hộp dự kiến','boxes','number',d.boxes,'min="1" max="60" required','Khoảng 10 hộp cho một phòng ít đồ.')}${inputField('Số món cồng kềnh','bulky','number',d.bulky,'min="0" max="30" required','Ví dụ: bàn, ghế, tủ nhỏ. Cần khảo sát thực tế.')}</div><label class="check-row"><input type="checkbox" name="packing" ${d.packing?'checked':''}><span>Tôi muốn hỗ trợ đóng gói<br><small class="muted">Đã gồm trong gói Trọn gói.</small></span></label>`;}else if(bookingStep===2){content=`<div class="form-title"><h2>Phòng mới của bạn ở đâu?</h2><p>Phục vụ tại ${esc(config.area)}. Lịch chuyển sẽ được xác nhận sau khi liên hệ.</p></div><div class="field-grid">${inputField('Địa chỉ lấy đồ *','origin','text',d.origin,'required maxlength="300" autocomplete="street-address" placeholder="Số nhà, đường, phường tại Vinh"')}${inputField('Địa chỉ phòng mới *','destination','text',d.destination,'required maxlength="300" placeholder="Số nhà, đường, phường tại Vinh"')}${inputField('Ngày chuyển dự kiến *','date','date',d.date,`required min="${new Date(Date.now()+7*3600000).toISOString().slice(0,10)}"`)}${selectField('Khung giờ mong muốn','slot',slots,d.slot)}${inputField('Khoảng cách dự kiến (km)','distance','number',d.distance,'min="1" max="80" required','Bạn ước tính giúp BOXANH; chưa tích hợp bản đồ.')}${inputField('Tầng lấy đồ','originFloor','number',d.originFloor,'min="0" max="15" required','Tầng trệt = 0.')}${inputField('Tầng phòng mới','destinationFloor','number',d.destinationFloor,'min="0" max="15" required')}</div><label class="check-row"><input type="checkbox" name="originElevator" ${d.originElevator?'checked':''}>Nơi lấy đồ có thang máy sử dụng được</label><label class="check-row"><input type="checkbox" name="destinationElevator" ${d.destinationElevator?'checked':''}>Nơi đến có thang máy sử dụng được</label><div class="notice">Nếu cần giao hộp trước, nên đặt trước 2–3 ngày. BOXANH sẽ thống nhất lịch giao và thu hồi khi khảo sát.</div>`;}else if(bookingStep===3){content=`<div class="form-title"><h2>Đồ nào không đi cùng bạn?</h2><p>Không bắt buộc. Mỗi món đồ được đánh giá riêng trước khi tiếp nhận.</p></div>${selectField('Cách xử lý mong muốn','surplusMode',modes,d.surplusMode)}<label class="field">Mô tả đồ không mang theo<textarea name="surplusDescription" maxlength="1500" placeholder="Ví dụ: quạt còn hoạt động, bàn học gỗ 80 cm…">${esc(d.surplusDescription)}</textarea></label>${photoField(d.photos)}<div class="notice mt20">Thu mua: chỉ giảm phí sau khi chốt giá và tiếp nhận đồ. Ký gửi: thanh toán sau khi bán được. Đồ hỏng: kiểm tra đầu ra trước khi xác nhận thu gom.</div>`;}else{content=`<div class="form-title"><h2>BOXANH liên hệ với bạn thế nào?</h2><p>Kiểm tra thông tin lần cuối. Gửi yêu cầu chưa đồng nghĩa với lịch đã được xác nhận.</p></div><div class="field-grid">${inputField('Họ và tên *','name','text',d.name,'required maxlength="100" autocomplete="name"')}${inputField('Số điện thoại *','phone','tel',d.phone,'required maxlength="25" autocomplete="tel" placeholder="0xxx xxx xxx"')}</div><label class="field">Lưu ý cho BOXANH<textarea name="notes" maxlength="1500" placeholder="Hẻm nhỏ, đồ dễ vỡ, chỗ đỗ xe, thời gian cần lưu ý…">${esc(d.notes)}</textarea></label><div class="tracking-meta"><div><small>Gói dịch vụ</small>${esc(services[d.service])}</div><div><small>Ngày chuyển dự kiến</small>${esc(d.date)} · ${esc(slots[d.slot])}</div><div><small>Từ</small>${esc(d.origin)}</div><div><small>Đến</small>${esc(d.destination)}</div><div><small>Hộp / đồ lớn</small>${d.boxes} hộp · ${d.bulky} món</div><div><small>Đồ thừa</small>${esc(modes[d.surplusMode])}</div></div><label class="check-row"><input type="checkbox" name="consent" required ${d.consent?'checked':''}><span>Tôi đồng ý để BOXANH xử lý thông tin, ảnh đã gửi và liên hệ về yêu cầu này theo <a class="text-link" href="/chinh-sach#bao-mat" target="_blank">chính sách quyền riêng tư</a>.</span></label><label class="honeypot">Website<input name="website" tabindex="-1" autocomplete="off"></label>`;}
  main.innerHTML=`${top('Một khởi đầu nhẹ nhàng.','Cho BOXANH biết vài điều về lần chuyển trọ của bạn. Chúng mình sẽ cùng khảo sát và chốt kế hoạch.','Đặt lịch chuyển trọ')}<div class="container form-layout"><form class="form-panel" id="booking-form"><div class="stepper">${steps.map((s,i)=>`<div class="step ${i+1===bookingStep?'active':i+1<bookingStep?'done':''}" ${i+1===bookingStep?'aria-current="step"':''}><b>0${i+1}</b>${s}</div>`).join('')}</div>${content}<div class="form-buttons">${bookingStep>1?'<button type="button" class="button outline" id="back-step">Quay lại</button>':'<a class="button outline" href="/dich-vu">Xem bảng giá</a>'}<button type="submit" class="button primary">${bookingStep===4?'Gửi yêu cầu báo giá':'Tiếp tục'}</button></div></form><aside class="quote-box"><span class="tag">${config.priceMode==='reference'?'BÁO GIÁ DỰ KIẾN':'ƯỚC TÍNH CỦA BẠN'}</span><h3 class="mt20">Chuyển trọ vừa với bạn.</h3><div id="quote-result"><p>Đang tính giá theo thông tin của bạn…</p></div><p>Chưa trừ đồ thu mua. Chỉ chốt giá sau khảo sát và thống nhất các khoản phát sinh.</p><div class="quote-foot">Cần trao đổi ngay?<br><a class="text-link" href="tel:${esc(config.phone)}">${esc(config.phone.replace(/(\d{4})(\d{3})(\d{3})/,'$1 $2 $3'))}</a></div></aside></div>`;
  const form=$('#booking-form');wirePhotos(form,bookingDraft);$('#back-step')?.addEventListener('click',()=>{captureFields(form,bookingDraft);bookingStep--;bookingPage();});form.addEventListener('input',()=>{captureFields(form,bookingDraft);clearTimeout(form.quoteTimer);form.quoteTimer=setTimeout(updateQuote,250);});form.addEventListener('change',()=>{captureFields(form,bookingDraft);updateQuote();});form.addEventListener('submit',async e=>{e.preventDefault();captureFields(form,bookingDraft);if(bookingStep===3&&bookingDraft.surplusMode!=='none'&&!bookingDraft.surplusDescription.trim()){formError(form,new Error('Mô tả đồ không mang theo để BOXANH thẩm định.'));return;}if(bookingStep<4){bookingStep++;bookingPage();main.scrollIntoView({block:'start',behavior:'instant'});return;}const btn=$('button[type=submit]',form);btn.disabled=true;btn.textContent='Đang gửi yêu cầu…';try{const result=await api('/api/bookings',bookingDraft);successPage(result.code,'BOXANH đã nhận yêu cầu của bạn.','Chúng mình sẽ liên hệ để khảo sát và xác nhận lịch. Vui lòng lưu mã để theo dõi tiến độ.');bookingStep=1;bookingDraft=freshBooking();}catch(error){formError(form,error);btn.disabled=false;btn.textContent='Gửi yêu cầu báo giá';}});updateQuote();}
async function updateQuote(){const version=++quoteVersion;try{const q=await api('/api/quote',bookingDraft);if(version!==quoteVersion||!$('#quote-result'))return;$('#quote-result').innerHTML=`<div class="quote-amount">Từ ${money(q.total)}</div>${q.lines.map(l=>`<div class="quote-line"><span>${esc(l.label)}</span><strong>${money(l.amount)}</strong></div>`).join('')}<div class="quote-line"><span>Thời gian thuê hộp</span><strong>${q.rentalDays} ngày</strong></div>`;}catch(error){if($('#quote-result'))$('#quote-result').innerHTML=`<p>${esc(error.message)}</p>`;}}

function surveyRequestPage(){const d=bookingDraft;const handover=d.service==='handover';main.innerHTML=`${top(handover?'Bàn giao phòng, có người cùng lo.':'Dọn phòng, theo đúng nhu cầu.','Gửi tình trạng phòng và hạng mục bạn cần. BOXANH khảo sát, tách rõ chi phí rồi mới xác nhận lịch.',services[d.service])}<div class="container form-layout"><form id="survey-form" class="form-panel"><h2 class="mb20">Thông tin ${services[d.service].toLowerCase()}</h2><div class="field-grid">${selectField('Dịch vụ','service',{cleaning:'Dọn phòng',handover:'Bàn giao phòng'},d.service)}${inputField('Diện tích phòng dự kiến (m²)','roomArea','number',d.roomArea||20,'required min="1" max="500"')}${inputField('Địa chỉ phòng *','origin','text',d.origin,'required maxlength="300" autocomplete="street-address"')}${inputField('Ngày mong muốn *','date','date',d.date,`required min="${new Date(Date.now()+7*3600000).toISOString().slice(0,10)}"`)}${selectField('Khung giờ mong muốn','slot',slots,d.slot)}${inputField('Họ và tên *','name','text',d.name,'required maxlength="100" autocomplete="name"')}${inputField('Số điện thoại *','phone','tel',d.phone,'required maxlength="25" autocomplete="tel"')}</div><label class="field">Hiện trạng & hạng mục cần hỗ trợ *<textarea name="notes" required maxlength="1500" placeholder="Sàn, nhà vệ sinh, bếp; đồ còn lại; sửa chữa cần khảo sát; yêu cầu của chủ phòng…">${esc(d.notes)}</textarea></label>${photoField(d.photos)}<label class="check-row mt20"><input name="consent" type="checkbox" required ${d.consent?'checked':''}><span>Tôi đồng ý để BOXANH xử lý thông tin và liên hệ theo <a class="text-link" href="/chinh-sach#bao-mat">chính sách quyền riêng tư</a>.</span></label><div class="form-buttons"><a class="text-link" href="/dich-vu">Xem dịch vụ</a><button type="submit" class="button primary">Gửi yêu cầu báo giá</button></div></form><aside class="quote-box"><span class="tag">BÁO GIÁ SAU KHẢO SÁT</span><h3 class="mt20">Cần khảo sát</h3><p class="mt20">Giá phụ thuộc diện tích, hiện trạng, hạng mục vệ sinh, yêu cầu sửa chữa và nguồn lực thực tế. Chưa có bảng giá cố định cho dịch vụ này.</p><p>Phí chờ, thêm người, ngoài giờ và sửa chữa nếu có phải được tách riêng, thống nhất trước khi thực hiện.</p><p>Gửi yêu cầu chưa xác nhận lịch hoặc thu tiền.</p></aside></div>`;const form=$('#survey-form');wirePhotos(form,d);form.addEventListener('change',e=>{captureFields(form,d);if(e.target.name==='service')surveyRequestPage();});form.addEventListener('submit',async e=>{e.preventDefault();captureFields(form,d);const button=$('button[type=submit]',form);button.disabled=true;button.textContent='Đang gửi…';try{const r=await api('/api/bookings',{...d,boxes:0,destination:d.origin,distance:1,bulky:0,packing:false,surplusMode:'none',surplusDescription:''});successPage(r.code,'BOXANH đã nhận yêu cầu báo giá.','CSKH sẽ liên hệ để khảo sát phòng và thống nhất phạm vi, chi phí, lịch thực hiện.');bookingDraft=freshBooking();bookingStep=1;}catch(error){formError(form,error);button.disabled=false;button.textContent='Gửi yêu cầu báo giá';}});}
let supportDraft={requestId:crypto.randomUUID(),code:'',phone:'',type:'missing',boxId:'',sealId:'',description:'',photos:[],consent:false};
function supportPage(){const d=supportDraft;main.innerHTML=`${top('Có vấn đề với đồ đạc?<br>BOXANH tiếp nhận cùng bạn.','Gửi mã đơn và thông tin bạn quan sát được. CSKH kiểm tra hồ sơ trước khi trao đổi phương án xử lý.','CSKH & sự cố')}<div class="container form-layout"><form class="form-panel" id="issue-form"><h2 class="mb20">Thông tin cần kiểm tra</h2><div class="field-grid">${inputField('Mã đơn BOXANH *','code','text',d.code,'required maxlength="30" placeholder="BX-…"')}${inputField('Số điện thoại của đơn *','phone','tel',d.phone,'required maxlength="25"')}${selectField('Vấn đề cần hỗ trợ','type',{missing:'Không tìm thấy đồ',seal:'Tem niêm phong rách / bất thường',damage:'Đồ hư hỏng',box:'Hộp / lịch thu hồi',other:'Vấn đề khác'},d.type)}${inputField('Mã hộp (nếu có)','boxId','text',d.boxId,'maxlength="80" placeholder="BX-000128"')}${inputField('Mã tem niêm phong (nếu có)','sealId','text',d.sealId,'maxlength="80"')}</div><label class="field">Món đồ, tình trạng & thời điểm phát hiện *<textarea name="description" required minlength="10" maxlength="2000" placeholder="Đồ có được đặt trong hộp không? Ai nhận/giao? Bạn phát hiện lúc nào?…">${esc(d.description)}</textarea></label>${photoField(d.photos,false,true)}<label class="check-row mt20"><input type="checkbox" name="consent" required ${d.consent?'checked':''}><span>Tôi đồng ý để BOXANH xử lý thông tin, ảnh và liên hệ về sự cố theo <a class="text-link" href="/chinh-sach#bao-mat">chính sách quyền riêng tư</a>.</span></label><button class="button primary mt20" type="submit">Gửi thông tin cho CSKH</button></form><aside class="support-panel"><h3>Giữ lại thông tin để đối chiếu</h3><ol class="support-steps"><li>Giữ hộp và tem niêm phong; chụp lại dấu hiệu bất thường.</li><li>Ghi mã đơn, mã hộp, mã tem niêm phong và món đồ liên quan.</li><li>CSKH đối chiếu đơn, lịch sử QR nếu có, tem niêm phong, ảnh giao nhận và danh sách đồ ngoài hộp.</li><li>Ghi nhận kết quả kiểm tra và phương án xử lý với các bên.</li></ol><p>Đồ ngoài hộp cần xác minh việc tiếp nhận bằng danh sách hoặc hình ảnh bàn giao riêng.</p><a class="text-link" href="/chinh-sach#su-co">Trách nhiệm & bồi thường dự kiến</a><p class="mt20">Cần trao đổi ngay? <a class="text-link" href="tel:${esc(config.phone)}">${esc(config.phone.replace(/(\d{4})(\d{3})(\d{3})/,'$1 $2 $3'))}</a></p></aside></div>`;const form=$('#issue-form');wirePhotos(form,d);form.addEventListener('submit',async e=>{e.preventDefault();captureFields(form,d);const btn=$('button[type=submit]',form);btn.disabled=true;btn.textContent='Đang gửi…';try{const r=await api('/api/issues',d);successPage(r.code,'CSKH đã nhận thông tin của bạn.','Vui lòng giữ lại hộp, tem niêm phong và hình ảnh liên quan. Mã này dùng để tra cứu tiến độ tiếp nhận sự cố.');supportDraft={requestId:crypto.randomUUID(),code:'',phone:'',type:'missing',boxId:'',sealId:'',description:'',photos:[],consent:false};}catch(error){formError(form,error);btn.disabled=false;btn.textContent='Gửi thông tin cho CSKH';}});}
function renderIssues(el){const issues=adminData.issues||[];const labels={received:'Đã tiếp nhận',reviewing:'Đang kiểm tra',resolved:'Đã ghi nhận kết quả'};el.innerHTML=issues.length?issues.map(issue=>`<article class="support-panel mb20"><div class="section-head"><h3>${esc(issue.code)}</h3><span class="tag">${labels[issue.status]}</span></div><p>Đơn ${esc(issue.booking_code)} · ${esc(issue.phone)} · ${esc({missing:'Không tìm thấy đồ',seal:'Tem niêm phong bất thường',damage:'Đồ hư hỏng',box:'Hộp / thu hồi',other:'Khác'}[issue.type])}</p><p>Hộp ${esc(issue.box_id||'Chưa ghi mã')} · Tem niêm phong ${esc(issue.seal_id||'Chưa ghi mã')}</p><p>${esc(issue.description)}</p><div class="upload-previews">${issue.photos.map(p=>`<img src="${esc(p.url)}" alt="Ảnh sự cố do khách cung cấp">`).join('')}</div><form data-issue="${issue.id}">${selectField('Trạng thái','status',nextOptions(['received','reviewing','resolved'],labels,issue.status,'resolved'),issue.status)}<label class="field">Nội dung phản hồi khách (hiển thị khi tra cứu)<textarea name="note" maxlength="2000">${esc(issue.note)}</textarea></label><button class="button primary mt20" type="submit">Lưu xử lý</button></form></article>`).join(''):emptyAdmin('Chưa có sự cố được gửi.','Thông tin từ biểu mẫu CSKH sẽ xuất hiện tại đây.');$$('[data-issue]',el).forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const input={};captureFields(form,input);const btn=$('button',form);btn.disabled=true;try{await api('/api/admin/issues/'+form.dataset.issue,input);await adminPage();toast('Đã lưu ghi nhận CSKH.');}catch(error){formError(form,error);btn.disabled=false;}}));}
function successPage(ref,title,message){main.innerHTML=`<div class="container"><section class="success-box"><div class="success-icon">✓</div><h1>${esc(title)}</h1><p>${esc(message)}</p><div class="reference-code">${esc(ref)}</div><div class="success-actions"><button class="button outline" id="copy-code">Sao chép mã</button><a class="button primary" href="/tra-cuu?ma=${encodeURIComponent(ref)}">Tra cứu yêu cầu</a></div><p class="sample-label mt20">Chưa thu tiền hoặc xác nhận giữ chỗ. Nếu cần gấp, gọi <a class="text-link" href="tel:${esc(config.phone)}">${esc(config.phone.replace(/(\d{4})(\d{3})(\d{3})/,'$1 $2 $3'))}</a>.</p></section></div>`;$('#copy-code').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(ref);toast('Đã sao chép mã yêu cầu.');}catch{toast('Bạn có thể chọn và sao chép mã hiển thị.');}});window.scrollTo({top:0,behavior:'instant'});}
function freshGoods(){return {requestId:crypto.randomUUID(),mode:'buyback',category:'furniture',condition:'good',description:'',bookingCode:'',name:'',phone:'',photos:[],consent:false};} let goodsDraft=freshGoods();
function goodsPage(){const selected=new URLSearchParams(location.search).get('phuong-an');if(['buyback','consign','recycle'].includes(selected))goodsDraft.mode=selected;const d=goodsDraft;main.innerHTML=`${top('Đồ còn tốt, trao tiếp thôi.','Gửi hình ảnh và tình trạng đồ. BOXANH kiểm tra khả năng tiếp nhận, rồi trao đổi phương án với bạn.','Thu mua & ký gửi')}<div class="container form-layout"><form class="form-panel" id="goods-form"><div class="form-title"><h2>Cho món đồ một cơ hội mới.</h2><p>Không phải món đồ nào cũng có thể thu mua hoặc tái chế.</p></div><div class="field-grid">${selectField('Bạn muốn làm gì?','mode',{buyback:modes.buyback,consign:modes.consign,recycle:modes.recycle},d.mode)}${selectField('Nhóm đồ','category',Object.fromEntries(Object.entries(categories).filter(([k])=>k!=='all')),d.category)}${selectField('Tình trạng','condition',{good:'Còn tốt, sử dụng bình thường',fair:'Đã cũ, còn sử dụng được',broken:'Hỏng / không còn sử dụng'},d.condition)}${inputField('Mã đơn chuyển trọ (nếu có)','bookingCode','text',d.bookingCode,'maxlength="30" placeholder="BX-…"','Cùng số điện thoại để liên kết giảm phí thu mua.')}</div><label class="field">Mô tả đồ *<textarea name="description" required maxlength="2000" placeholder="Tên đồ, số lượng, kích thước, tuổi sử dụng và lỗi nếu có…">${esc(d.description)}</textarea></label>${photoField(d.photos)}<div class="spacer"></div><div class="field-grid">${inputField('Họ và tên *','name','text',d.name,'required maxlength="100" autocomplete="name"')}${inputField('Số điện thoại *','phone','tel',d.phone,'required maxlength="25" autocomplete="tel"')}</div><label class="check-row"><input type="checkbox" name="consent" required ${d.consent?'checked':''}><span>Tôi đồng ý để BOXANH xử lý thông tin, ảnh và liên hệ về yêu cầu theo <a class="text-link" href="/chinh-sach#bao-mat" target="_blank">chính sách quyền riêng tư</a>.</span></label><label class="honeypot">Website<input name="website" tabindex="-1" autocomplete="off"></label><div class="form-buttons"><a class="button outline" href="/do-cu">Xem vòng đời mới</a><button class="button primary" type="submit">Gửi đồ để thẩm định</button></div></form><aside class="quote-box"><span class="tag">THỐNG NHẤT TRƯỚC KHI TIẾP NHẬN</span><h3 class="mt20">Ba cách xử lý, ba thỏa thuận rõ ràng.</h3><div class="three-choices"><div><span class="choice-mark">1</span><div><strong>Thu mua</strong><p>Định giá, kiểm tra, tiếp nhận. Có thể giảm phí đơn liên quan khi đồ đã được nhận.</p></div></div><div><span class="choice-mark">2</span><div><strong>Ký gửi</strong><p>Thỏa thuận giá và phí. Chỉ thanh toán sau khi bán, theo số tiền thực nhận.</p></div></div><div><span class="choice-mark">3</span><div><strong>Phân loại / thu gom</strong><p>Xác nhận loại đồ, phí nếu có và đơn vị tiếp nhận phù hợp.</p></div></div></div><p>Pin, hóa chất, rác nguy hại và vật sắc nhọn không thuộc luồng thu gom thông thường.</p></aside></div>`;const form=$('#goods-form');wirePhotos(form,goodsDraft);form.addEventListener('input',()=>captureFields(form,goodsDraft));form.addEventListener('change',()=>captureFields(form,goodsDraft));form.addEventListener('submit',async e=>{e.preventDefault();captureFields(form,goodsDraft);const btn=$('button[type=submit]',form);btn.disabled=true;try{const result=await api('/api/goods',goodsDraft);successPage(result.code,'Món đồ của bạn đã có hồ sơ.','BOXANH sẽ xem ảnh, đánh giá tình trạng và liên hệ trước khi định giá hoặc nhận đồ.');goodsDraft=freshGoods();}catch(error){formError(form,error);btn.disabled=false;}});}

function wireProductDetails(items,sample=false){$$('[data-product]').forEach(btn=>btn.addEventListener('click',()=>{const p=items.find(x=>String(x.id)===btn.dataset.product);if(!p)return;const dialog=$('#detail-dialog');$('#dialog-content').innerHTML=`<div class="dialog-header"><span class="tag">${sample?'BỘ SƯU TẬP THAM KHẢO':esc(p.condition)}</span><button class="icon-button" id="close-dialog" aria-label="Đóng chi tiết">×</button></div><div class="spacer"></div><img src="${esc(apiAsset(p.image))}" alt="${esc(p.name)}"><h2 id="detail-title">${esc(p.name)}</h2><div class="product-price">${money(p.price)}</div><p>${esc(p.description)}</p>${sample?'<div class="notice">Đây là ý tưởng tham khảo, chưa có hàng để đặt mua.</div>':`<form id="interest-form"><div class="field-grid">${inputField('Họ tên *','name','text','','required maxlength="100"')}${inputField('Số điện thoại *','phone','tel','','required maxlength="25"')}</div><label class="check-row"><input type="checkbox" name="consent" required><span>Tôi đồng ý để BOXANH liên hệ về món đồ và xử lý thông tin theo <a class="text-link" href="/chinh-sach#bao-mat" target="_blank">chính sách quyền riêng tư</a>.</span></label><button class="button primary" type="submit">Đăng ký quan tâm</button><p class="sample-label">BOXANH xác nhận tình trạng và khả dụng trước giao dịch. Chưa thanh toán hoặc giữ món đồ.</p></form>`}`;$('#close-dialog').addEventListener('click',()=>dialog.close());dialog.showModal();const form=$('#interest-form');if(form){const rid=crypto.randomUUID();form.addEventListener('submit',async e=>{e.preventDefault();const data={requestId:rid,productId:p.id};captureFields(form,data);const button=$('button[type=submit]',form);button.disabled=true;try{const r=await api('/api/interests',data);dialog.close();successPage(r.code,'Đã nhận đăng ký quan tâm.','BOXANH sẽ liên hệ để xác nhận món đồ và thống nhất việc giao nhận.');}catch(error){formError(form,error);button.disabled=false;}});}}));}
async function marketPage(generation){main.innerHTML=top('Đồ cũ với bạn.<br>Khởi đầu mới với người khác.','Những món đồ còn giá trị xứng đáng được sử dụng tiếp. Tìm đồ phù hợp hoặc gửi món đồ bạn không mang đi.','Vòng đời mới')+'<div class="container loading">Đang xem các món đồ…</div>';let products;try{products=await api('/api/products');}catch(error){if(generation===routeGeneration)main.innerHTML+=`<div class="container notice">${esc(error.message)}</div>`;return;}if(generation!==routeGeneration)return;const sample=products.length===0,items=sample?sampleProducts:products;main.innerHTML=`${top('Đồ cũ với bạn.<br>Khởi đầu mới với người khác.','Tìm món đồ vừa với phòng mới, hoặc trao tiếp món đồ còn tốt. Mỗi giao dịch cần xác nhận tình trạng và khả dụng.','Vòng đời mới')}<section class="container"><div class="notice ${sample?'':'green'}">${sample?'BOXANH đang chuẩn bị danh mục đồ thực tế. Dưới đây là bộ sưu tập ý tưởng với hình ảnh và giá tham khảo, chưa mở bán.':'Danh mục đồ được BOXANH đăng. Hãy đăng ký quan tâm để xác nhận tình trạng, khả dụng và giao nhận trước thanh toán.'}</div><div class="filter-row">${Object.entries(categories).map(([k,v])=>`<button class="filter-chip ${k==='all'?'active':''}" data-category="${k}">${v}</button>`).join('')}<label class="sr-only" for="product-search">Tìm món đồ</label><input class="search-input" id="product-search" placeholder="Tìm món đồ cho phòng mới…" type="search"></div><div class="products" id="product-grid">${productCards(items,sample)}</div></section><section class="section container"><div class="cta-panel"><div><h2>Không mang theo?<br>Để BOXANH cùng bạn tìm đầu ra.</h2><p>Thu mua, ký gửi hoặc phân loại sau khi kiểm tra.</p></div><a class="button light large" href="/gui-do">Gửi đồ cần xử lý</a></div></section>`;let category='all';function filter(){const search=$('#product-search').value.toLocaleLowerCase('vi');const shown=items.filter(p=>(category==='all'||p.category===category)&&(p.name+' '+p.description).toLocaleLowerCase('vi').includes(search));$('#product-grid').innerHTML=shown.length?productCards(shown,sample):'<div class="empty-state"><h3>Chưa có món đồ phù hợp.</h3><p>Thử nhóm khác hoặc đổi từ khóa.</p></div>';wireProductDetails(shown,sample);}$$('[data-category]').forEach(btn=>btn.addEventListener('click',()=>{category=btn.dataset.category;$$('[data-category]').forEach(b=>b.classList.toggle('active',b===btn));filter();}));$('#product-search').addEventListener('input',filter);wireProductDetails(items,sample);}

function trackingPage(){const ref=new URLSearchParams(location.search).get('ma')||'';main.innerHTML=`${top('Hành trình của bạn đến đâu rồi?','Dùng mã yêu cầu và số điện thoại đã đăng ký để xem tiến độ dịch vụ, thu mua, ký gửi, quan tâm đồ cũ hoặc xử lý sự cố.','Tra cứu yêu cầu')}<div class="container tracking-layout"><form class="tracking-card" id="track-form">${inputField('Mã yêu cầu *','code','text',ref,'required maxlength="30" placeholder="BX-… hoặc DG-…" autocomplete="off"')}${inputField('Số điện thoại đăng ký *','phone','tel','','required maxlength="25" autocomplete="tel"')}<button class="button primary" type="submit">Xem tiến độ</button><p class="sample-label mt20">Mã có trong màn hình xác nhận khi gửi yêu cầu. Cần hỗ trợ? Gọi ${esc(config.phone.replace(/(\d{4})(\d{3})(\d{3})/,'$1 $2 $3'))}.</p></form><div id="tracking-result" class="tracking-card"><div class="empty-state"><h3>Chúng mình luôn cập nhật.</h3><p>Tiến độ sẽ xuất hiện ở đây khi bạn tra cứu đúng thông tin.</p></div></div></div>`;const form=$('#track-form');form.addEventListener('submit',async e=>{e.preventDefault();const input={};captureFields(form,input);const btn=$('button[type=submit]',form);btn.disabled=true;try{const r=await api('/api/track',input);$('.form-error',form)?.remove();if(r.kind==='booking'){const active=r.steps.findIndex(s=>s.status===r.status);$('#tracking-result').innerHTML=`<div class="section-head"><h3>Yêu cầu ${esc(r.code)}</h3><span class="tag">${esc(r.label)}</span></div><div class="tracking-meta"><div><small>Gói dịch vụ</small>${esc(services[r.service])}</div><div><small>Ngày dự kiến</small>${esc(r.date)}</div><div><small>Giá ${r.finalQuote===null?'dự kiến':'đã chốt'}</small>${r.finalQuote===null&&['cleaning','handover'].includes(r.service)?'Chờ khảo sát':money(r.finalQuote??r.estimate)}</div><div><small>Giảm phí thu mua đã nhận</small>${money(r.credit)}</div></div>${r.finalQuote!==null?`<div class="notice green mt20">Phí sau giảm: ${money(Math.max(0,r.finalQuote-r.credit))}${r.credit>r.finalQuote?'. Phần giá trị thu mua vượt phí cần được hai bên đối soát riêng.':''}.</div>`:''}${r.status==='cancelled'?'<div class="notice mt20">Yêu cầu đã hủy theo trao đổi với BOXANH.</div>':`<ol class="timeline">${r.steps.map((s,i)=>{const ev=r.events.find(e=>e.status===s.status);return `<li class="${i<active?'done':i===active?'current':''}">${esc(s.label)}<small>${ev?esc(new Date(ev.created_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})):i>active?'Chưa thực hiện':''}</small></li>`;}).join('')}</ol>`}`;}else if(r.kind==='goods')$('#tracking-result').innerHTML=`<span class="tag">${esc(r.label)}</span><h3 class="mt20">Hồ sơ ${esc(r.code)}</h3><div class="tracking-meta mt20"><div><small>Phương án</small>${esc(modes[r.mode])}</div><div><small>Nhóm đồ</small>${esc(categories[r.category])}</div><div><small>Định giá</small>${r.valuation===null?'Đang thẩm định':money(r.valuation)}</div><div><small>Tiền thanh toán đã ghi nhận</small>${r.payout===null?'Chưa ghi nhận':money(r.payout)}</div></div><div class="notice mt20">${r.mode==='consign'?'Giá định giá không phải khoản được trừ ngay vào phí chuyển. Ký gửi thanh toán sau khi bán và đối soát.':'Định giá cần được thống nhất trước tiếp nhận. Giảm phí chỉ áp dụng cho thu mua đã nhận đồ và được liên kết với đơn chuyển trọ.'}</div>`;else if(r.kind==='issue')$('#tracking-result').innerHTML=`<span class="tag">${esc(r.label)}</span><h3 class="mt20">Sự cố ${esc(r.code)}</h3><p class="mt20">Liên quan đơn ${esc(r.bookingCode)}. CSKH kiểm tra hồ sơ và liên hệ theo số điện thoại của đơn.</p><p class="mt20">${esc(r.note||'Chưa có kết quả kiểm tra được ghi nhận.')}</p>`;else $('#tracking-result').innerHTML=`<span class="tag">${esc({received:'Đã nhận đăng ký',contacted:'Đã liên hệ',completed:'Hoàn tất',cancelled:'Đã hủy'}[r.status])}</span><h3 class="mt20">${esc(r.product)}</h3><p class="mt20">Mã ${esc(r.code)}. BOXANH sẽ trao đổi về tình trạng món đồ và giao nhận.</p>`;}catch(error){formError(form,error);}btn.disabled=false;});}

function aboutPage(){return `${top('Chuyển nơi ở.<br>Giữ lại những điều tốt đẹp.','BOXANH bắt đầu từ một câu hỏi: làm sao để mỗi lần chuyển trọ bớt vất vả, và những món đồ còn tốt không bị bỏ lại?','Về BOXANH')}<section class="section container about-layout"><img src="/assets/moving.webp" alt="Minh họa tinh thần BOXANH: chuyển trọ bằng hộp dùng nhiều lần"><div><div class="eyebrow">TỪ MỘT LẦN CHUYỂN TRỌ</div><h2>Chúng mình lo cả hành trình.</h2><p>Mua thùng, tìm xe, đóng đồ, xử lý đồ thừa rồi dọn vật liệu đóng gói — một lần chuyển trọ thường có nhiều việc hơn bạn nghĩ.</p><p>BOXANH tập trung vào ba nhóm dịch vụ: chuyển trọ, dọn phòng và bàn giao phòng. Hộp dùng nhiều lần hỗ trợ vận chuyển; đồ không mang theo có phương án tiếp nhận riêng sau thẩm định.</p><p id="khu-vuc">Dự án đang chuẩn bị triển khai tại <strong>${esc(config.area)}</strong>. Mọi lịch, giá và đầu ra đồ cũ được xác nhận trước khi thực hiện.</p></div></section><section class="section section-tint"><div class="container"><div class="section-head"><div><div class="eyebrow">LỜI HỨA CỦA BOXANH</div><h2>Rõ ràng từ đầu.<br>Có trách nhiệm đến cuối.</h2></div></div><div class="cards-three"><article class="price-card"><h3>Giá được thống nhất</h3><p class="mt20">Khảo sát, giải thích các khoản phí và xác nhận trước khi chuyển. Thông tin thay đổi cần trao đổi lại.</p></article><article class="price-card"><h3>Đồ được kiểm đếm</h3><p class="mt20">Lập danh sách, ghi nhận tình trạng và giao nhận rõ ràng. Chính sách xử lý sự cố cần được chốt trong đơn dịch vụ.</p></article><article class="price-card"><h3>Sống xanh có căn cứ</h3><p class="mt20">Theo dõi việc dùng lại hộp và xử lý đồ. Chỉ công bố kết quả môi trường khi có dữ liệu và đầu ra được xác nhận.</p></article></div></div></section><section class="section container"><div class="cta-panel"><div><h2>Cùng tạo một cách chuyển trọ tốt hơn.</h2><p>Trao đổi về dịch vụ, đồ cũ hoặc cơ hội hợp tác.</p></div><a class="button light large" href="tel:${esc(config.phone)}">Gọi ${esc(config.phone.replace(/(\d{4})(\d{3})(\d{3})/,'$1 $2 $3'))}</a></div></section>`;}
function policyPage(){return `${top('Rõ ràng để yên tâm.','Nguyên tắc dịch vụ và xử lý thông tin trong giai đoạn thử nghiệm. Các điều khoản thương mại cụ thể được thống nhất trong từng đơn.','Chính sách')}<div class="container policy-content"><div class="notice">Bản chính sách vận hành dự kiến. Cần BOXANH xác nhận và hoàn thiện điều khoản trước khi đưa dịch vụ vào kinh doanh chính thức.</div><h2>1. Tiếp nhận và xác nhận lịch</h2><p>Biểu mẫu trên website tạo yêu cầu khảo sát, chưa xác nhận đội xe, lịch trống hoặc hợp đồng dịch vụ. BOXANH liên hệ qua số điện thoại đã đăng ký để thống nhất phạm vi, giá và lịch.</p><h2>2. Báo giá và thanh toán</h2><p>Giá trên website ${config.priceMode==='reference'?'đang là giá tham khảo':'được tính theo bảng giá hiện hành'} dựa trên thông tin khách nhập. Báo giá cuối cùng được xác nhận sau khảo sát. Website chưa tích hợp thanh toán trực tuyến; không yêu cầu khách chuyển tiền tại màn hình gửi yêu cầu.</p><p>Thay đổi số đồ, địa chỉ, tầng, khả năng tiếp cận hoặc yêu cầu đóng gói có thể thay đổi phí. Khoản bổ sung phải được thống nhất trước khi thực hiện.</p><h2>3. Hộp tái sử dụng</h2><p>Hộp được kiểm đếm lúc giao và nhận lại. Thời gian thuê dự kiến ${config.rentalDays} ngày. Gia hạn dự kiến ${money(config.extraBoxDay)}/hộp/ngày. Đặt cọc, kích thước, tải trọng và trách nhiệm khi mất/hỏng được xác nhận trong thỏa thuận cụ thể.</p><h2>4. Thu mua và ký gửi</h2><p>Thu mua cần đánh giá tình trạng, thống nhất giá và tiếp nhận đồ. Chỉ đồ đã được tiếp nhận và liên kết đúng đơn mới được ghi giảm phí. Giá trị vượt phí dịch vụ phải được đối soát riêng.</p><p>Ký gửi cần thỏa thuận mức giá, phí, thời hạn bán, việc trả đồ nếu chưa bán được và cách thanh toán. Tiền chỉ thanh toán sau khi bán và đối soát; không trừ trước từ giá trị ước tính.</p><h2>5. Đồ hỏng và thu gom</h2><p>Tiếp nhận phụ thuộc loại đồ và đầu ra phù hợp. BOXANH chưa công bố đối tác tái chế đã ký kết. Không nhận mặc định pin, hóa chất, rác nguy hại hoặc vật sắc nhọn qua quy trình thông thường. Không cam kết mọi món đồ thu gom đều được tái chế.</p><h2>6. Đổi lịch, hủy và sự cố</h2><p>Liên hệ ${esc(config.phone)} để yêu cầu thay đổi hoặc hủy. Chi phí đã phát sinh, thời hạn báo trước, trách nhiệm mất/hỏng và mức bồi thường phải được thỏa thuận trước khi xác nhận dịch vụ; website hiện chưa tự động thu phí hủy.</p><h2 id="su-co">Trách nhiệm đồ đạc và tiếp nhận sự cố</h2><p>Trước khi xác nhận, cần thỏa thuận bằng văn bản về danh sách đồ được tiếp nhận, hiện trạng, phạm vi trách nhiệm, giới hạn bồi thường và bằng chứng cần cung cấp. BOXANH chưa công bố gói bảo hiểm, mức đền bù cố định hoặc cam kết bảo hiểm toàn bộ đồ đạc.</p><p>Khi phát hiện tem niêm phong rách, mã không khớp, đồ hư hỏng hoặc không tìm thấy đồ: giữ hộp và tem niêm phong, chụp tình trạng, ghi rõ mã đơn, mã hộp, mã tem niêm phong, món đồ và thời điểm phát hiện. CSKH tiếp nhận, đối chiếu lịch sử QR nếu đã triển khai, ảnh nhận/giao và hồ sơ liên quan, rồi ghi nhận phương án xử lý với các bên.</p><p>Đồ không bỏ vào hộp cần có danh sách và hình ảnh bàn giao riêng. Việc không tìm thấy đồ sau kiểm tra không tự động chứng minh đồ đã được giao cho đối tác. CSKH cần xác minh việc tiếp nhận và quá trình xử lý trước khi xác định trách nhiệm.</p><p>Hộp thu hồi được kiểm tra và vệ sinh trước khi dùng lại. Hộp lỗi chuyển Bảo trì; hộp không xác định được vị trí ghi Thất lạc trong hệ thống quản lý theo mã dự kiến.</p><a class="text-link" href="/ho-tro">Gửi thông tin cho CSKH</a><h2 id="bao-mat">7. Thông tin và quyền riêng tư</h2><p>BOXANH tiếp nhận họ tên, số điện thoại, địa chỉ lấy/giao đồ, lịch, mô tả và ảnh bạn chủ động gửi để khảo sát, thực hiện dịch vụ và đối soát. Không gửi giấy tờ định danh hoặc thông tin nhạy cảm không cần thiết.</p><p>Thông tin và ảnh được lưu tại hệ thống của BOXANH, chỉ truy cập qua cổng vận hành có mật khẩu. Tra cứu công khai cần mã yêu cầu và số điện thoại; không hiển thị địa chỉ đầy đủ hoặc ảnh hồ sơ.</p><p>Thông tin chỉ nên cung cấp cho nhân sự hoặc đối tác cần thiết để thực hiện dịch vụ đã thống nhất. Trước khi vận hành chính thức, BOXANH cần công bố đơn vị chịu trách nhiệm dữ liệu, thời hạn lưu giữ và quy trình yêu cầu truy cập, chỉnh sửa, xóa. Trong giai đoạn thử nghiệm, liên hệ ${esc(config.phone)} để yêu cầu xử lý thông tin.</p><h3>Trò chuyện với trợ lý Bơ</h3><p>Khi bạn đồng ý và dùng chế độ AI, nội dung hội thoại được gửi qua máy chủ BOXANH đến OpenAI để tạo câu trả lời. Không nhập mật khẩu, OTP, thông tin thanh toán hoặc dữ liệu nhạy cảm. Website không lưu hội thoại vào cơ sở dữ liệu; hội thoại chỉ được giữ trong bộ nhớ của phiên trang đang mở. Yêu cầu AI sử dụng store:false; việc xử lý dữ liệu của nhà cung cấp vẫn theo chính sách áp dụng của OpenAI.</p><p>Chế độ cẩm nang được ghi rõ và xử lý trên trình duyệt. Bơ chỉ hỗ trợ thông tin và bản nháp; bạn kiểm tra và tự gửi yêu cầu trên biểu mẫu. Giá và lịch cuối cùng cần nhân sự BOXANH xác nhận.</p><h2>8. Hình ảnh và danh mục minh họa</h2><p>Nhân vật mặc đồng phục BOXANH ở trang chủ là hình minh họa thương hiệu được tạo bằng AI, không phải ảnh nhân viên thực tế. Hình hộp ý tưởng ở trang hộp tái sử dụng chỉ minh họa thiết kế, không phải ảnh hàng đã sản xuất. Ảnh phòng và chuyển nhà là ảnh chụp tham khảo có giấy phép từ Unsplash và Pexels; không phải ảnh đội ngũ, khách hàng hay căn phòng tại Vinh của BOXANH. Các hình dịch vụ ở đầu trang là minh họa, không phải ảnh công trình hoặc đơn hàng đã thực hiện. Các thẻ thuộc bộ sưu tập ý tưởng chưa phải hàng đang bán. BOXANH sẽ bổ sung ảnh thực tế khi triển khai.</p></div>`;}

function nextOptions(steps,labels,current,terminal){const i=steps.indexOf(current);const keys=[current];if(!['paid','completed','rejected','cancelled'].includes(current)){if(steps[i+1])keys.push(steps[i+1]);if(terminal==='cancelled'||i<steps.indexOf('collected'))keys.push(terminal);}return Object.fromEntries(keys.map(k=>[k,labels[k]]));}
let adminTab='bookings';
let adminData;
let adminSearch='';
async function adminPage(generation=routeGeneration){main.innerHTML=top('Cổng vận hành BOXANH.','Quản lý yêu cầu, hộp tái sử dụng và đồ đang tìm vòng đời mới.','Vận hành')+'<div class="container loading">Đang kiểm tra phiên vận hành…</div>';try{adminData=await api('/api/admin/dashboard');if(generation!==routeGeneration)return;adminDashboard();}catch(error){if(generation!==routeGeneration)return;if(error.status!==401){main.innerHTML+=`<div class="container notice">${esc(error.message)}</div>`;return;}main.innerHTML=`${top('Chào người giữ hành trình xanh.','Đăng nhập để tiếp nhận và vận hành các yêu cầu BOXANH.','Vận hành')}<div class="container"><form class="form-panel admin-login" id="admin-login"><h2 class="mb20">Đăng nhập vận hành</h2>${inputField('Mật khẩu quản trị','password','password','','required autocomplete="current-password"')}<button class="button primary" type="submit">Vào cổng vận hành</button><p class="sample-label mt20">Dành cho nhân sự BOXANH được cấp quyền. Liên hệ người quản lý nếu cần hỗ trợ.</p></form></div>`;const form=$('#admin-login');form.addEventListener('submit',async e=>{e.preventDefault();const button=$('button',form);button.disabled=true;try{await api('/api/admin/login',{password:$('[name=password]',form).value});await adminPage();}catch(error){formError(form,error);button.disabled=false;}});}}
function adminDashboard(){const d=adminData,active=d.bookings.filter(b=>!['completed','cancelled'].includes(b.status)),goods=d.goods.filter(g=>!['paid','completed','rejected'].includes(g.status));main.innerHTML=`${top('Mọi hành trình, trong một nơi.','Dữ liệu đang lưu trên hệ thống BOXANH. Cập nhật sau khi đã thống nhất với khách.','Vận hành')}<section class="container admin-panel"><div class="admin-bar"><div><span class="tag">${esc(d.config.area)}</span><p class="sample-label mt20">Giá: ${d.config.priceMode==='reference'?'dự kiến':'chính thức'} · ${d.config.bookingEnabled?'đang nhận yêu cầu':'tạm ngưng nhận lịch'}</p></div><div class="inline-buttons"><a class="button outline" href="/api/admin/export" download>Xuất đơn CSV</a><button class="button outline" id="admin-logout">Đăng xuất</button></div></div><div class="admin-stats"><div class="stat-card"><span>Đơn đang xử lý</span><strong>${active.length}</strong></div><div class="stat-card"><span>Hộp sạch sẵn sàng</span><strong>${d.inventory.available}</strong></div><div class="stat-card"><span>Hộp đang giao</span><strong>${d.inventory.allocated}</strong></div><div class="stat-card"><span>Hồ sơ đồ cần xử lý</span><strong>${goods.length}</strong></div></div><div class="admin-tabs">${Object.entries({bookings:'Đơn dịch vụ',goods:'Thu mua / ký gửi',inventory:'Kho hộp',products:'Danh mục đồ',interests:'Khách quan tâm',settings:'Cấu hình & giá',issues:'CSKH & sự cố',guide:'Đối tác & QR',audit:'Nhật ký'}).map(([k,v])=>`<button class="button ${adminTab===k?'primary':'outline'}" data-admin-tab="${k}">${v}</button>`).join('')}</div><div id="admin-content"></div></section>`;$('#admin-logout').addEventListener('click',async()=>{await api('/api/admin/logout',{});adminData=undefined;adminPage();});$$('[data-admin-tab]').forEach(btn=>btn.addEventListener('click',()=>{adminTab=btn.dataset.adminTab;adminSearch='';adminDashboard();}));adminContent();}
function emptyAdmin(title,detail){return `<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`;}
function adminContent(){const d=adminData,el=$('#admin-content');if(adminTab==='bookings'){el.innerHTML=`<div class="filter-row"><h3>Đơn dịch vụ</h3><label class="sr-only" for="admin-search">Tìm đơn theo mã, tên hoặc điện thoại</label><input id="admin-search" class="search-input" type="search" placeholder="Mã đơn, tên, điện thoại…" value="${esc(adminSearch)}"></div><div id="admin-bookings"></div>`;function update(){const q=adminSearch.toLocaleLowerCase('vi'),rows=d.bookings.filter(b=>(b.code+' '+b.name+' '+b.phone+' '+d.statusLabels[b.status]).toLocaleLowerCase('vi').includes(q));$('#admin-bookings').innerHTML=rows.length?table(['Mã / khách','Lịch dự kiến','Gói','Trạng thái','Giá dự kiến',''],rows.map(b=>`<tr><td><strong>${esc(b.code)}</strong><br>${esc(b.name)} · ${esc(b.phone)}</td><td>${esc(b.payload.date)}<br>${esc(slots[b.payload.slot])}</td><td>${esc(services[b.payload.service])}</td><td><span class="tag">${esc(d.statusLabels[b.status])}</span></td><td>${['cleaning','handover'].includes(b.payload.service)?'Chờ khảo sát':money(b.estimate)}</td><td><button class="button outline" data-booking-id="${b.id}">Xử lý</button></td></tr>`).join('')):emptyAdmin('Chưa có đơn phù hợp.','Yêu cầu gửi từ trang đặt lịch sẽ xuất hiện ở đây.');$$('[data-booking-id]').forEach(btn=>btn.addEventListener('click',()=>adminBooking(Number(btn.dataset.bookingId))));}$('#admin-search').addEventListener('input',e=>{adminSearch=e.target.value;update();});update();}
  else if(adminTab==='guide'){el.innerHTML=operatingGuide();}else if(adminTab==='issues'){renderIssues(el);}else if(adminTab==='goods'){el.innerHTML=d.goods.length?table(['Mã / khách','Nhóm đồ','Hình thức','Trạng thái','Định giá',''],d.goods.map(g=>`<tr><td><strong>${esc(g.code)}</strong><br>${esc(g.name)} · ${esc(g.phone)}</td><td>${esc(categories[g.category])}</td><td>${esc(modes[g.mode])}</td><td><span class="tag">${esc(d.goodsLabels[g.status])}</span></td><td>${g.valuation===null?'Chưa định giá':money(g.valuation)}</td><td><button class="button outline" data-goods-id="${g.id}">Thẩm định</button></td></tr>`).join('')):emptyAdmin('Chưa có hồ sơ đồ.','Yêu cầu thu mua, ký gửi và phân loại sẽ xuất hiện ở đây.');$$('[data-goods-id]').forEach(btn=>btn.addEventListener('click',()=>adminGoods(Number(btn.dataset.goodsId))));}
  else if(adminTab==='inventory'){const inv=d.inventory;el.innerHTML=`<div class="inventory-grid"><div class="inventory-card"><h3>Hộp sạch sẵn sàng</h3><strong>${inv.available}</strong><p>Đã trừ ${inv.reserved} hộp giữ cho lịch xác nhận.</p></div><div class="inventory-card"><h3>Hộp chờ vệ sinh</h3><strong>${inv.cleaning}</strong><p>Hộp thu hồi cần vệ sinh trước khi dùng lại.</p></div><div class="inventory-card"><h3>Hộp ngừng sử dụng</h3><strong>${inv.retired}</strong><p>Hỏng hoặc đã loại khỏi vòng sử dụng.</p></div></div><div class="spacer"></div><form id="inventory-form" class="form-panel admin-settings"><h3 class="mb20">Kiểm đếm kho</h3><div class="field-grid">${inputField('Tổng số hộp sở hữu','total','number',inv.total,'min="0" max="100000" required')}${inputField('Hộp chờ vệ sinh','cleaning','number',inv.cleaning,'min="0" max="100000" required')}${inputField('Hộp ngừng sử dụng','retired','number',inv.retired,'min="0" max="100000" required')}</div><div class="notice">Hộp đang giao (${inv.allocated}) và hộp giữ cho lịch (${inv.reserved}) được tính từ đơn. Nhập số hộp nhận tốt, hỏng hoặc mất trong đơn; hộp tốt nhận lại đi vào nhóm chờ vệ sinh. Sau vệ sinh thực tế, giảm số chờ vệ sinh tại đây.</div><button class="button primary mt20" type="submit">Lưu kiểm đếm</button></form>`;wireAdminForm('#inventory-form','/api/admin/inventory');}
  else if(adminTab==='settings'){const c=d.config;el.innerHTML=`<form id="settings-form" class="form-panel admin-settings"><h3 class="mb20">Thông tin và bảng giá</h3><div class="field-grid">${inputField('Khu vực phục vụ','area','text',c.area,'required maxlength="150"')}${inputField('Điện thoại liên hệ','phone','tel',c.phone,'required')}${inputField('Email (không bắt buộc)','email','email',c.email||'','maxlength="200"')}${selectField('Trạng thái bảng giá','priceMode',{reference:'Giá dự kiến / tham khảo',official:'Bảng giá chính thức'},c.priceMode)}${inputField('Gói Gọn nhẹ (đ)','smallBase','number',c.smallBase,'min="0" max="10000000" required')}${inputField('Gói Trọn gói (đ)','fullBase','number',c.fullBase,'min="0" max="10000000" required')}${inputField('Giao + thu hồi hộp thuê (đ)','boxBase','number',c.boxBase,'min="0" max="10000000" required')}${inputField('Hộp bổ sung / hộp thuê (đ)','boxUnit','number',c.boxUnit,'min="0" max="10000000" required')}${inputField('Km thêm ngoài 5 km (đ)','distanceUnit','number',c.distanceUnit,'min="0" max="10000000" required')}${inputField('Mỗi tầng không có thang máy (đ)','stairsUnit','number',c.stairsUnit,'min="0" max="10000000" required')}${inputField('Mỗi món cồng kềnh (đ)','bulkyUnit','number',c.bulkyUnit,'min="0" max="10000000" required')}${inputField('Đóng gói bổ sung (đ)','packingFee','number',c.packingFee,'min="0" max="10000000" required')}${inputField('Số ngày thuê hộp','rentalDays','number',c.rentalDays,'min="1" max="30" required')}${inputField('Gia hạn / hộp / ngày (đ)','extraBoxDay','number',c.extraBoxDay,'min="0" max="10000000" required')}</div><label class="check-row"><input name="bookingEnabled" type="checkbox" ${c.bookingEnabled?'checked':''}>Cho phép tiếp nhận yêu cầu chuyển trọ mới</label><div class="notice">Bảng giá cập nhật áp dụng cho ước tính mới. Đơn đã nhận giữ nguyên giá ước tính, giá chốt và lịch sử xử lý.</div><button class="button primary mt20" type="submit">Lưu cấu hình & bảng giá</button></form>`;wireAdminForm('#settings-form','/api/admin/config',()=>{config={...adminData.config};updateContact();});}
  else if(adminTab==='products'){const sourceGoods=Object.fromEntries([['','Đồ của BOXANH / chưa liên kết'],...d.goods.filter(g=>['collected','listed','paid'].includes(g.status)&&g.mode!=='recycle'&&!(g.mode==='consign'&&g.status==='paid')).map(g=>[String(g.id),g.code+' · '+g.name+' · '+modes[g.mode]])]);el.innerHTML='<div class="notice mb20">Chỉ đăng đồ đã kiểm tra và có quyền bán. Đăng ảnh thật của món đồ; ảnh sẽ được công khai trong danh mục.</div>'+(d.products.length?table(['Món đồ','Nhóm','Giá','Hiển thị',''],d.products.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+esc(categories[p.category])+'</td><td>'+money(p.price)+'</td><td>'+(p.available?'Đang hiển thị':'Đã ẩn')+'</td><td><button class="button outline" data-availability="'+p.id+'" data-value="'+(p.available?'0':'1')+'">'+(p.available?'Ẩn món đồ':'Hiện món đồ')+'</button></td></tr>').join('')):emptyAdmin('Chưa đăng món đồ thực tế.','Danh mục đang hiển thị bộ sưu tập ý tưởng có nhãn tham khảo.'))+'<div class="spacer"></div><form id="product-form" class="form-panel admin-settings"><h3 class="mb20">Đăng món đồ</h3><div class="field-grid">'+inputField('Tên món đồ','name','text','','required maxlength="150"')+selectField('Nhóm đồ','category',Object.fromEntries(Object.entries(categories).filter(([k])=>k!=='all')),'furniture')+inputField('Giá bán (đ)','price','number',0,'min="0" max="100000000" required')+inputField('Tình trạng hiển thị','condition','text','','required maxlength="100" placeholder="Ví dụ: Đã kiểm tra, còn tốt"')+selectField('Hồ sơ nguồn','goodsId',sourceGoods,'')+'</div><label class="field">Mô tả, lỗi và điều kiện giao nhận<textarea name="description" required maxlength="2000"></textarea></label>'+photoField([],true)+'<div class="spacer"></div><button class="button primary" type="submit">Đăng món đồ</button></form>';const imageDraft={photos:[]};wirePhotos($('#product-form'),imageDraft);wireAdminForm('#product-form','/api/admin/products',undefined,imageDraft);$$('[data-availability]').forEach(btn=>btn.addEventListener('click',async()=>{try{await api('/api/admin/products/'+btn.dataset.availability,{available:btn.dataset.value==='1'});await adminPage();toast('Đã cập nhật hiển thị.');}catch(error){toast(error.message);}}));}
  else if(adminTab==='interests'){el.innerHTML=d.interests.length?table(['Mã / khách','Món đồ','Trạng thái','Cập nhật'],d.interests.map(i=>`<tr><td><strong>${esc(i.code)}</strong><br>${esc(i.name)} · ${esc(i.phone)}</td><td>${esc(i.product_name)}</td><td>${esc({received:'Đã nhận',contacted:'Đã liên hệ',completed:'Hoàn tất',cancelled:'Đã hủy'}[i.status])}</td><td><form data-interest-id="${i.id}"><label class="sr-only" for="interest-${i.id}">Trạng thái ${esc(i.code)}</label><select id="interest-${i.id}" name="status">${Object.entries({received:'Đã nhận',contacted:'Đã liên hệ',completed:'Hoàn tất',cancelled:'Đã hủy'}).map(([k,v])=>`<option value="${k}" ${i.status===k?'selected':''}>${v}</option>`).join('')}</select> <button class="button outline" type="submit">Lưu</button></form></td></tr>`).join('')):emptyAdmin('Chưa có đăng ký quan tâm.','Khách đăng ký từ món đồ thật sẽ xuất hiện ở đây.');$$('[data-interest-id]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/interests/'+form.dataset.interestId,{status:$('select',form).value});await adminPage();toast('Đã cập nhật.');}catch(error){toast(error.message);}}));}
  else if(adminTab==='audit'){el.innerHTML=d.audit.length?table(['Thời gian','Thao tác','Mã hồ sơ'],d.audit.map(a=>`<tr><td>${esc(new Date(a.created_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}))}</td><td>${esc(a.action)}</td><td>${esc(a.record_id)}</td></tr>`).join('')):emptyAdmin('Chưa có thao tác.','Nhật ký sẽ ghi nhận việc tạo và cập nhật hồ sơ.');}}
function wireAdminForm(selector,url,after,extraDraft={}){const form=$(selector);form.addEventListener('submit',async e=>{e.preventDefault();const input={...extraDraft};captureFields(form,input);const btn=$('button[type=submit]',form);btn.disabled=true;try{await api(url,input);await adminPage();after?.();toast('Đã lưu cập nhật.');}catch(error){formError(form,error);btn.disabled=false;}});}
function detailRows(rows){return `<div class="data-list">${rows.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div>`;}
function adminBooking(id){const b=adminData.bookings.find(b=>b.id===id);if(!b)return;const p=b.payload;$('#admin-content').innerHTML=`<div class="admin-bar"><h2>Đơn ${esc(b.code)}</h2><button class="button outline" id="back-admin">Về danh sách</button></div><div class="admin-detail"><div class="form-panel"><h3>Thông tin khảo sát</h3>${detailRows([['Khách hàng',b.name],['Điện thoại',b.phone],['Địa chỉ lấy đồ',p.origin],['Địa chỉ giao đồ',p.destination],['Ngày dự kiến',p.date],['Khung giờ',slots[p.slot]],['Gói dịch vụ',services[p.service]],['Số hộp',p.boxes],['Km dự kiến',p.distance],['Tầng lấy / đến',p.originFloor+' / '+p.destinationFloor],['Thang máy lấy / đến',(p.originElevator?'Có':'Không')+' / '+(p.destinationElevator?'Có':'Không')],['Đồ cồng kềnh',p.bulky],['Đồ thừa',modes[p.surplusMode]],['Giá dự kiến',['cleaning','handover'].includes(p.service)?'Chờ khảo sát':money(b.estimate)],['Diện tích phòng',p.roomArea?p.roomArea+' m²':'Không áp dụng'],['Thu mua đã nhận',money(b.buyback_credit)]])}<p class="admin-note">${esc(p.notes||'Không có ghi chú thêm.')}</p>${p.surplusDescription?`<p class="admin-note"><strong>Đồ không mang:</strong> ${esc(p.surplusDescription)}</p>`:''}<div class="photo-grid mt20">${b.photos.map(photo=>`<a href="${photo.url}" target="_blank"><img src="${photo.url}" alt="Ảnh khảo sát đồ của đơn ${esc(b.code)}"></a>`).join('')}</div></div><form class="form-panel" id="booking-admin-form"><h3>Cập nhật sau khi trao đổi với khách</h3>${selectField('Trạng thái','status',nextOptions(b.steps,adminData.statusLabels,b.status,'cancelled'),b.status)}${inputField('Giá dịch vụ đã chốt (đ)','finalQuote','number',b.final_quote??'','min="0" max="100000000"','Để trống khi chưa khảo sát/chốt giá. Chưa trừ thu mua.')}${inputField('Giảm phí thu mua đã tiếp nhận (đ)','credit','number',b.buyback_credit,'disabled','Tính từ hồ sơ thu mua liên kết đã nhận đồ; không tính ký gửi.')}${b.allocation?.delivered?`<div class="notice green mb20">Đang giao ${b.allocation.boxes-b.allocation.returned}/${b.allocation.boxes} hộp.</div><div class="field-grid">${inputField('Hộp tốt nhận thêm lần này','goodReturn','number',0,'min="0" max="60"')}${inputField('Hộp hỏng nhận thêm lần này','damagedReturn','number',0,'min="0" max="60"')}${inputField('Hộp mất đối soát thêm lần này','lost','number',0,'min="0" max="60"','Ghi rõ thỏa thuận với khách trong ghi chú.')}</div>`:''}<label class="field">Ghi chú nội bộ<textarea name="note" maxlength="1500">${esc(b.note)}</textarea></label><div class="notice">Chỉ xác nhận khi đã trao đổi với khách. ${p.boxes>0?'Xác nhận lịch sẽ giữ hộp trong kho.':'Dọn/bàn giao phòng không giữ hộp trong kho.'} Kiểm đếm số nhận lại thực tế; hộp tốt vào nhóm chờ vệ sinh, hộp hỏng/mất vào nhóm ngừng sử dụng. Không dùng trạng thái để thay thế kiểm đếm thực tế.</div><button type="submit" class="button primary mt20">Lưu tiến độ & báo giá</button><div class="notice green mt20">${b.final_quote===null?'Chưa có báo giá chốt.':'Phí sau giảm: '+money(Math.max(0,b.final_quote-b.buyback_credit))+'.'}</div></form></div>`;$('#back-admin').addEventListener('click',adminContent);const form=$('#booking-admin-form');form.addEventListener('submit',async e=>{e.preventDefault();const raw=$('[name=finalQuote]',form).value;const input={status:$('[name=status]',form).value,finalQuote:raw===''?null:Number(raw),note:$('[name=note]',form).value,goodReturn:Number($('[name=goodReturn]',form)?.value||0),damagedReturn:Number($('[name=damagedReturn]',form)?.value||0),lost:Number($('[name=lost]',form)?.value||0)};const btn=$('button[type=submit]',form);btn.disabled=true;try{await api('/api/admin/bookings/'+id,input);adminData=await api('/api/admin/dashboard');adminBooking(id);toast('Đã cập nhật đơn.');}catch(error){formError(form,error);btn.disabled=false;}});}
function adminGoods(id){const g=adminData.goods.find(g=>g.id===id);if(!g)return;$('#admin-content').innerHTML=`<div class="admin-bar"><h2>Hồ sơ ${esc(g.code)}</h2><button class="button outline" id="back-admin">Về danh sách</button></div><div class="admin-detail"><div class="form-panel"><h3>Đồ đang tìm vòng đời mới</h3>${detailRows([['Khách hàng',g.name],['Điện thoại',g.phone],['Nhóm đồ',categories[g.category]],['Phương án',modes[g.mode]],['Tình trạng',{good:'Còn tốt',fair:'Đã cũ, còn dùng',broken:'Hỏng'}[g.condition]],['Đơn liên kết',g.booking_code||'Chưa liên kết']])}<p class="admin-note">${esc(g.description)}</p><div class="photo-grid mt20">${g.photos.map(photo=>`<a href="${photo.url}" target="_blank"><img src="${photo.url}" alt="Ảnh đồ của hồ sơ ${esc(g.code)}"></a>`).join('')}</div></div><form class="form-panel" id="goods-admin-form"><h3>Thẩm định & đối soát</h3>${selectField('Trạng thái','status',nextOptions(g.steps,adminData.goodsLabels,g.status,'rejected'),g.status)}${inputField('Định giá / giá đề nghị (đ)','valuation','number',g.valuation??'','min="0" max="100000000"')}${inputField('Tiền trả trực tiếp đã ghi nhận (đ)','payout','number',g.payout??'','min="0" max="100000000"')}${g.mode==='buyback'?inputField('Phân bổ trừ phí đơn liên kết (đ)','credit','number',g.service_credit,'min="0" max="100000000"','Giảm phí + tiền trả trực tiếp không vượt giá thu mua.'):''}<label class="field">Ghi chú nội bộ / thỏa thuận<textarea name="note" maxlength="1500">${esc(g.note)}</textarea></label><div class="notice">${g.mode==='buyback'?'Khi đã tiếp nhận đồ (Đã tiếp nhận / Đã thanh toán), giá thu mua được tính giảm phí đơn liên kết. Chỉ cập nhật sau kiểm tra và đồng ý của khách.':g.mode==='consign'?'Ký gửi thanh toán sau bán; định giá không được trừ ngay vào phí chuyển. Ghi rõ phí ký gửi và thời điểm đối soát.':'Cần ghi nhận đơn vị tiếp nhận và đầu ra phù hợp trước khi xác nhận thu gom hoặc tái chế.'}</div><button class="button primary mt20" type="submit">Lưu thẩm định</button></form></div>`;$('#back-admin').addEventListener('click',adminContent);const form=$('#goods-admin-form');form.addEventListener('submit',async e=>{e.preventDefault();const val=$('[name=valuation]',form).value,pay=$('[name=payout]',form).value,input={status:$('[name=status]',form).value,valuation:val===''?null:Number(val),payout:pay===''?null:Number(pay),credit:Number($('[name=credit]',form)?.value||0),note:$('[name=note]',form).value};const btn=$('button[type=submit]',form);btn.disabled=true;try{await api('/api/admin/goods/'+id,input);adminData=await api('/api/admin/dashboard');adminGoods(id);toast('Đã lưu thẩm định.');}catch(error){formError(form,error);btn.disabled=false;}});}

function syncContact(){document.querySelectorAll('[data-contact-area]').forEach(el=>el.textContent=config.area);document.querySelectorAll('[data-contact-link=call]').forEach(a=>a.href='tel:'+config.phone);const text=config.phone.replace(/(\d{4})(\d{3})(\d{3})/,'$1 $2 $3');const header=$('.header-phone');if(header){header.href='tel:'+config.phone;if(!header.querySelector('[data-contact-phone]'))header.textContent=text;}document.querySelectorAll('[data-contact-phone]').forEach(el=>el.textContent=text);const floating=$('.floating-contact');if(floating){floating.href='tel:'+config.phone;floating.setAttribute('aria-label','Gọi BOXANH '+text);}}
function updateContact(){syncContact();if(config.publicPreview)document.querySelector('.footer-grid a[href="/quan-tri"]')?.remove();$('#footer-contact').innerHTML=`${esc(config.area)}<br><a href="tel:${esc(config.phone)}">${esc(config.phone.replace(/(\d{4})(\d{3})(\d{3})/,'$1 $2 $3'))}</a>${config.email?`<a href="mailto:${esc(config.email)}">${esc(config.email)}</a>`:''}`;}
function registerQuoteTool(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(context.registerTool({name:'configure_move_quote',title:'Ước tính chuyển trọ BOXANH',description:'Chuẩn bị gói, số hộp và thông tin vận chuyển trong biểu mẫu, hiển thị giá dự kiến. Không gửi yêu cầu hoặc xác nhận lịch.',inputSchema:{type:'object',properties:{service:{type:'string',enum:['small','full','boxes']},boxes:{type:'integer',minimum:1,maximum:60},distance:{type:'integer',minimum:1,maximum:80},originFloor:{type:'integer',minimum:0,maximum:15},destinationFloor:{type:'integer',minimum:0,maximum:15},originElevator:{type:'boolean'},destinationElevator:{type:'boolean'},bulky:{type:'integer',minimum:0,maximum:30},packing:{type:'boolean'}},required:['service','boxes','distance'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||typeof input!=='object')throw new Error('Thông tin báo giá chưa hợp lệ.');const keys=['service','boxes','distance','originFloor','destinationFloor','originElevator','destinationElevator','bulky','packing'];if(Object.keys(input).some(k=>!keys.includes(k)))throw new Error('Chỉ nhập thông tin tính báo giá.');const staged=Object.fromEntries(keys.filter(k=>input[k]!==undefined).map(k=>[k,input[k]])),q=await api('/api/quote',staged);bookingDraft={...bookingDraft,...staged};bookingStep=1;go('/dat-lich');await updateQuote();return {estimate:q.total,currency:'VND',service:q.service,boxes:q.boxes,lines:q.lines,submitted:false};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}
try{
  if(config.apiBase){
    const controller=new AbortController();
    const configTimeout=setTimeout(()=>controller.abort(),3000);
    try{
      const response=await fetch('/api/config',{signal:controller.signal,credentials:'same-origin'});
      if(!response.ok)throw new Error('Không tải được cấu hình dịch vụ.');
      config={...config,...await response.json()};
    }finally{clearTimeout(configTimeout);}
  }else if(!embeddedConfig)config=await api('/api/config');
}catch{toast('Chưa tải được cập nhật dịch vụ. Giá đang hiển thị là tham khảo; vui lòng thử lại hoặc gọi BOXANH.');}
updateContact();
await render();
registerQuoteTool();
